export const weeks: Week[] = specs.map((s, index) => {
  const number = index + 1;
  const supplemental = number > 24;
  const activity = (suffix: string, track: Track, minutes: number, lesson: Lesson, added = false): Activity => ({ id: `w${number}-${suffix}`, week: number, track, title: lesson[0], description: lesson[1], acceptance: lesson[2], resourceIds: lesson[3], minutes, supplemental: supplemental || added });
  return { id: `w${number}`, number, month: Math.min(6, Math.ceil(number / 4)), title: s.title, goal: s.goal, prerequisites: [s.prerequisite || (number === 1 ? 'نیاز به پیش‌دانش برنامه‌نویسی نیست؛ نصب ابزار و دسترسی به ترمینال کافی است.' : `توانایی انجام و توضیح خروجی هفته ${number - 1}؛ هفته‌های آینده قفل نیستند.`)], deliverable: s.deliverable, criteria: [s.practice[2], s.aiPractice[2], s.systems[2], s.project[2]], questions: s.questions, supplemental, activities: [activity('backend-study', 'backend', 240, s.backend), activity('backend-practice', 'backend', 240, s.practice, true), activity('ai-study', 'ai', 90, s.ai), activity('ai-practice', 'ai', 90, s.aiPractice, true), activity('systems', 'systems', 120, s.systems, number > 24), activity('project', 'project', 120, s.project, true)] };
});
